-- Migration 438: intake XJZ craft material capture targets.
-- Function: crafting, forging, alchemy, refining, and gem recipe evidence worklist.
-- This does not promote formal recipes because material targets do not prove outputs or success rates.

CREATE TABLE IF NOT EXISTS god2_research.xjz_craft_material_capture_targets (
  target_id BIGINT NOT NULL COMMENT 'XJZ 合成材料補證目標 ID',
  client_item_id INT NOT NULL COMMENT '官方客戶端材料道具 ID',
  item_code VARCHAR(100) NULL COMMENT '客戶端道具代碼',
  item_prefix VARCHAR(50) NULL COMMENT '客戶端道具前綴',
  material_type_zh_tw VARCHAR(100) NULL COMMENT '材料類型',
  purpose_zh_tw VARCHAR(255) NULL COMMENT '材料用途',
  process_kind VARCHAR(50) NOT NULL COMMENT '製作流程類型',
  recipe_role VARCHAR(50) NOT NULL COMMENT '配方角色',
  suggested_life_skill_id BIGINT NULL COMMENT '建議生活技能 ID',
  capture_priority VARCHAR(20) NOT NULL COMMENT '補證優先度',
  request_hint_zh_tw VARCHAR(500) NOT NULL COMMENT '建議測試方式',
  current_client_source VARCHAR(100) NOT NULL COMMENT '目前客戶端來源',
  source_file VARCHAR(500) NOT NULL COMMENT '證據來源檔案',
  source_line INT NULL COMMENT '證據來源行號',
  evidence_status_zh_tw VARCHAR(100) NOT NULL COMMENT '目前證據狀態',
  needs_packet_evidence TINYINT(1) NOT NULL COMMENT '是否仍需要封包或黑箱證據',
  wanted_fields_zh_tw VARCHAR(500) NOT NULL COMMENT '需要補證欄位',
  formal_item_id BIGINT NULL COMMENT '正式服務端材料道具 ID',
  formal_item_name_zh_tw VARCHAR(200) NULL COMMENT '正式服務端材料名稱',
  formal_link_status_zh_tw VARCHAR(80) NOT NULL DEFAULT '待連結' COMMENT '正式道具連結狀態',
  created_at_utc DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6) COMMENT '建立 UTC 時間',
  PRIMARY KEY (target_id),
  UNIQUE KEY ux_xjz_craft_material_client_item (client_item_id),
  KEY ix_xjz_craft_material_formal_item (formal_item_id),
  KEY ix_xjz_craft_material_process (process_kind),
  KEY ix_xjz_craft_material_priority (capture_priority),
  CONSTRAINT ck_xjz_craft_material_needs_packet CHECK (needs_packet_evidence IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ 合成材料抓包與黑箱測試目標';

TRUNCATE TABLE god2_research.xjz_craft_material_capture_targets;

