UPDATE god2_research.xjz_craft_material_capture_targets target
JOIN god2_game.items item ON item.client_item_id = target.client_item_id
SET target.formal_item_id = item.item_id,
    target.formal_item_name_zh_tw = item.name_zh_tw,
    target.formal_link_status_zh_tw = '已連結正式道具';

UPDATE god2_research.xjz_craft_material_capture_targets
SET formal_link_status_zh_tw = '正式道具未建立'
WHERE formal_item_id IS NULL;

CREATE OR REPLACE VIEW god2_research.vw_xjz_craft_material_capture_targets_readable AS
SELECT target_id, client_item_id, formal_item_id, formal_item_name_zh_tw AS material_name_zh_tw,
       CASE process_kind WHEN 'forge' THEN '鍛造' WHEN 'alchemy' THEN '煉丹' WHEN 'refine' THEN '精煉' WHEN 'gem' THEN '寶石合成' ELSE '合成' END AS game_function_zh_tw,
       material_type_zh_tw, purpose_zh_tw, capture_priority, wanted_fields_zh_tw, request_hint_zh_tw,
       CASE needs_packet_evidence WHEN 1 THEN '需要抓包或黑箱測試' ELSE '已可套用' END AS evidence_need_zh_tw,
       formal_link_status_zh_tw, source_file, source_line
FROM god2_research.xjz_craft_material_capture_targets;

INSERT INTO god2_research.static_gap_remediation_queue
  (legacy_table_name, formal_table_name, priority_rank, remediation_category_zh_tw,
   game_function_zh_tw, evidence_policy_zh_tw, remediation_action_zh_tw,
   dependency_check_zh_tw, current_status_zh_tw, safe_to_apply_automatically,
   safe_to_drop_legacy_now, reviewed_at_utc)
SELECT 'xjz_craft_material_capture_targets', missing.formal_table_name, missing.priority_rank, '補證清單',
       missing.game_function_zh_tw,
       '材料身份可由客戶端與正式道具表確認，但配方成品、材料組合與成功率必須由抓包或黑箱測試補齊。',
       '已建立 xjz_craft_material_capture_targets 作為合成、鍛造、煉丹、精煉、寶石流程補證清單；未確認完整配方前不寫入正式製作表。',
       '正式 crafting_recipes 需要 life_skill_id，材料與產出表需要 recipe_id；目前只補測試目標，不建立假配方。',
       '已建立材料補證清單，正式配方待抓包或黑箱測試',
       0, 0, UTC_TIMESTAMP()
FROM (
  SELECT 'crafting_recipes' AS formal_table_name, 60 AS priority_rank, '生活技能製作配方' AS game_function_zh_tw UNION ALL
  SELECT 'crafting_recipe_materials', 61, '生活技能配方材料' UNION ALL
  SELECT 'crafting_recipe_outputs', 62, '生活技能配方產物'
) missing
WHERE NOT EXISTS (SELECT 1 FROM god2_research.static_gap_remediation_queue queue WHERE queue.formal_table_name = missing.formal_table_name);

UPDATE god2_research.static_gap_remediation_queue
SET remediation_category_zh_tw = '補證清單',
    evidence_policy_zh_tw = '材料身份可由客戶端與正式道具表確認，但配方成品、材料組合與成功率必須由抓包或黑箱測試補齊。',
    remediation_action_zh_tw = '已建立 xjz_craft_material_capture_targets 作為合成、鍛造、煉丹、精煉、寶石流程補證清單；未確認完整配方前不寫入正式製作表。',
    dependency_check_zh_tw = '正式 crafting_recipes 需要 life_skill_id，材料與產出表需要 recipe_id；目前只補測試目標，不建立假配方。',
    current_status_zh_tw = '已建立材料補證清單，正式配方待抓包或黑箱測試',
    safe_to_apply_automatically = 0,
    safe_to_drop_legacy_now = 0,
    reviewed_at_utc = UTC_TIMESTAMP()
WHERE formal_table_name IN ('crafting_recipes','crafting_recipe_materials','crafting_recipe_outputs');

UPDATE god2_research.formal_table_server_correspondence
SET server_correspondence_status_zh_tw = '服務端表存在；已補材料補證清單，正式配方待證據',
    runtime_usage_policy_zh_tw = '只有配方、材料、產物與成功率都有證據後才寫入正式製作表。',
    cleanup_decision_zh_tw = '保留正式空表；用 xjz_craft_material_capture_targets 作為補證來源。',
    reviewed_at_utc = UTC_TIMESTAMP(6)
WHERE schema_name = 'god2_game' AND table_name IN ('crafting_recipes','crafting_recipe_materials','crafting_recipe_outputs');
